using UnityEngine;\nusing UnityEngine.UI;\n\n/// <summary>\nUI component displaying player health bar.\n/// </summary>\npublic class HealthBarUI : MonoBehaviour\n{\n    [SerializeField] private Image healthFillImage;\n    [SerializeField] private TMPro.TextMeshProUGUI healthText;\n    [SerializeField] private Color healthyColor = Color.green;\n    [SerializeField] private Color criticalColor = Color.red;\n    [SerializeField] private Character character;\n    \n    private float currentHealthPercent = 1f;\n    private float targetHealthPercent = 1f;\n    private float lerpSpeed = 5f;\n    \n    private void Start()\n    {\n        if (character == null)\n        {\n            character = GetComponentInParent<Character>();\n        }\n        \n        CharacterStats.OnHealthChanged += UpdateHealthDisplay;\n    }\n    \n    private void OnDestroy()\n    {\n        CharacterStats.OnHealthChanged -= UpdateHealthDisplay;\n    }\n    \n    private void Update()\n    {\n        // Smooth health bar animation\n        currentHealthPercent = Mathf.Lerp(currentHealthPercent, targetHealthPercent, Time.deltaTime * lerpSpeed);\n        \n        if (healthFillImage != null)\n        {\n            healthFillImage.fillAmount = currentHealthPercent;\n            \n            // Color based on health\n            Color displayColor = Color.Lerp(criticalColor, healthyColor, currentHealthPercent);\n            healthFillImage.color = displayColor;\n        }\n    }\n    \n    private void UpdateHealthDisplay(float healthPercent)\n    {\n        targetHealthPercent = healthPercent;\n        \n        if (healthText != null && character != null)\n        {\n            float currentHP = character.GetStats().CurrentHP;\n            float maxHP = character.GetStats().MaxHP;\n            healthText.text = $\"{currentHP:F0} / {maxHP:F0}\";\n        }\n    }\n}\n"